(function () {
  var MIN = 3, MAXLIM = 50, DEFLIM = 25;
  // An unrouted JSONPath arrives as the literal "$.x" string, and the engine
  // also hands back the strings "undefined"/"null" for an absent key. Both are
  // emptiness, not data. (Same guard the occupation-lookup flow ships.)
  function cl(v) {
    if (v === undefined || v === null) return '';
    var s = String(v);
    if (s.indexOf('$.') === 0) return '';
    if (s === 'undefined' || s === 'null' || s === '[]' || s === '{}') return '';
    return s;
  }
  function num(v, d, max) {
    var n = parseInt(cl(v), 10);
    if (!(n > 0)) n = d;
    if (max && n > max) n = max;
    return n;
  }
  var k = cl(kind).toLowerCase().replace(/[^a-z_]/g, '');
  var raw = cl(q).trim();
  var val = cl(val_in).trim();
  var lim = num(limit, DEFLIM, MAXLIM);
  var off = num(offset, 0, 10000); if (!(off > 0)) off = 0;
  var sess = cl(session).replace(/[^A-Za-z0-9._-]/g, '').substring(0, 64);

  var KINDS = ['address', 'address_details', 'abn', 'abn_details', 'occupation'];
  var known = false;
  for (var i = 0; i < KINDS.length; i++) { if (KINDS[i] === k) known = true; }
  if (!known) {
    return { route: 'REJECT', kind: k, error: 'unsupported lookup kind', reason: 'unknown_kind',
             limit: lim, offset: off, session: sess };
  }

  var isSearch = (k === 'address' || k === 'abn' || k === 'occupation');
  // Below the minimum this returns an EMPTY PAGE, not an error: "keep typing" is
  // not a failure and must not paint a banner over the field. No upstream call
  // is made either way, which is the half that bounds spend.
  if (isSearch && raw.length < MIN) {
    return { route: 'REJECT', kind: k, reason: 'below_min_chars', min_chars: MIN,
             limit: lim, offset: off, session: sess };
  }
  if (!isSearch && val === '') {
    return { route: 'REJECT', kind: k, error: 'nothing selected to resolve', reason: 'no_value',
             limit: lim, offset: off, session: sess };
  }

  var out = { kind: k, reason: 'query', limit: lim, offset: off, session: sess,
              min_chars: MIN, query: raw, value: val, error: '' };

  if (k === 'occupation') {
    // Prefix per whitespace token against occupation_label, lowercased — the
    // index stores lowercase prefixes, so "PHYS" matches nothing. Tokens AND.
    var toks = raw.toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/^ +| +$/g, '').split(' ');
    var conditions = [{ field: 'occupation_active', keyword: 'true' }];
    for (var t = 0; t < toks.length; t++) {
      if (toks[t].length > 0) conditions.push({ field: 'occupation_label', prefix: toks[t] });
    }
    var FIELDS = { itpi: 'itpi_eligibility', itl: 'itpi_eligibility', itcl: 'itpi_eligibility',
                   ah: 'ah_eligibility', allied_health: 'ah_eligibility', ahcl: 'ah_eligibility',
                   gp: 'gp_eligibility', general_property: 'gp_eligibility' };
    var pkey = cl(product).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    var pfield = FIELDS[pkey] || '';
    if (pfield !== '') {
      var wantRaw = cl(eligibility); if (wantRaw === '') wantRaw = 'yes,refer';
      var parts = wantRaw.toLowerCase().split(','), want = [];
      for (var w = 0; w < parts.length; w++) {
        var p = parts[w].replace(/^ +| +$/g, '');
        if (p === 'yes' || p === 'no' || p === 'refer') want.push(p);
      }
      if (want.length === 0) want = ['yes', 'refer'];
      var group = [];
      for (var g = 0; g < want.length; g++) group.push({ field: pfield, keyword: want[g] });
      conditions.push({ operator: 'or', conditions: group });
    }
    out.route = 'OCC_FETCH';
    out.occ_filter = JSON.stringify({ conditions: conditions });
    out.occ_limit = String(lim);
    out.occ_offset = String(off);
    return out;
  }

  if (k === 'address') { out.route = 'ADDR_FETCH'; out.g_input = raw; return out; }
  if (k === 'address_details') { out.route = 'ADDR_DET_FETCH'; out.g_place_id = val; return out; }

  if (k === 'abn') {
    // ABR's MatchingNames is a NAME search. A caller who typed digits meant the
    // details hop, so route it there rather than name-searching for "51824753556".
    var digits = raw.replace(/[^0-9]/g, '');
    if (digits.length === 11 && raw.replace(/[0-9 ]/g, '') === '') {
      out.route = 'ABN_DET_FETCH'; out.abr_abn = digits; out.kind = 'abn_details'; return out;
    }
    out.route = 'ABN_FETCH'; out.abr_name = raw; out.abr_max = String(lim); return out;
  }

  // abn_details. Always a STRING on the wire: a bare JSON number becomes a Go
  // float64 and serialises into the query string as 3.3051775556e+10, which ABR
  // answers 200 with "Search text is not a valid ABN or ACN" — a wrong answer
  // that looks like a right one (§9).
  var d = val.replace(/[^0-9]/g, '');
  if (d.length !== 11) {
    return { route: 'REJECT', kind: k, error: 'an ABN is 11 digits', reason: 'bad_abn',
             limit: lim, offset: off, session: sess };
  }
  out.route = 'ABN_DET_FETCH'; out.abr_abn = d; return out;
})()

(function () {
  function obj(v) { return (v && typeof v === 'object' && Object.prototype.toString.call(v) !== '[object Array]') ? v : null; }
  function arr(v) { return Object.prototype.toString.call(v) === '[object Array]' ? v : []; }
  function str(v) { return (v === undefined || v === null) ? '' : String(v); }
  // An http node that never ran resolves to the literal "$.NODE" string.
  function node(v) { if (typeof v === 'string') return null; return obj(v); }
  // ABR is JSONP: a hard-coded callback( ... ) wrapper that &callback= does not
  // change, so http.go's json.Unmarshal fails and hands back the raw string.
  function jsonp(v) {
    var s = (v === undefined || v === null) ? '' : String(v);
    var a = s.indexOf('{'), b = s.lastIndexOf('}');
    if (a < 0 || b <= a) return null;
    try { return JSON.parse(s.substring(a, b + 1)); } catch (e) { return null; }
  }
  function page(options, total, off, extra) {
    var out = { options: options, total: total, count: options.length,
                has_more: (off + options.length) < total,
                next_offset: ((off + options.length) < total) ? (off + options.length) : null };
    if (extra) { for (var k in extra) { if (extra[k] !== undefined) out[k] = extra[k]; } }
    return out;
  }

  var p = obj(prep) || {};
  var off = parseInt(p.offset, 10); if (!(off > 0)) off = 0;
  var kind = str(p.kind);

  // ---- rejected before any upstream call ---------------------------------
  // PREPARE puts min_chars on its below_min_chars return. Rebuilding the
  // envelope here drops anything PREPARE added, so it is carried across
  // explicitly: without it the input can say "keep typing" but not how many,
  // which is the whole content of the hint.
  if (str(p.route) === 'REJECT') {
    var r = { options: [], total: 0, count: 0, has_more: false, next_offset: null,
              reason: str(p.reason) };
    var mc = parseInt(p.min_chars, 10);
    if (mc > 0) r.min_chars = mc;
    if (str(p.error) !== '') r.error = str(p.error);
    return r;
  }

  // ---- occupation: occupation_config records, no external API ------------
  var f = node(occ);
  if (f) {
    var src = obj(f.data) || {};
    var rows = arr(src.results);
    var total = typeof src.total_hits === 'number' ? src.total_hits : rows.length;
    var options = [];
    for (var i = 0; i < rows.length; i++) {
      var d = obj(rows[i] && rows[i].data) || {};
      var flags = [];
      if (d.itpi_eligibility) flags.push('ITPI ' + d.itpi_eligibility);
      if (d.ah_eligibility) flags.push('Allied Health ' + d.ah_eligibility);
      if (d.gp_eligibility) flags.push('General Property ' + d.gp_eligibility);
      // Prefill keys sit FLAT on the row: lookup.utils.readRowKey looks the key
      // up flat first and only then as a dotted path.
      options.push({
        value: str(d.occupation_code), text: str(d.occupation_label),
        note: (d.occupation_category ? 'ANZSIC ' + d.occupation_category + ' - ' : '') + flags.join(', '),
        occupation_code: d.occupation_code, occupation_label: d.occupation_label,
        occupation_category: d.occupation_category,
        itpi_eligibility: d.itpi_eligibility, ah_eligibility: d.ah_eligibility,
        gp_eligibility: d.gp_eligibility,
        itpi_hazard_class: d.itpi_hazard_class, ah_hazard_class: d.ah_hazard_class,
        itpi_question_set: d.itpi_question_set, ah_question_set: d.ah_question_set,
        gp_question_set: d.gp_question_set
      });
    }
    return page(options, total, off, { reason: 'query' });
  }

  // ---- address search: Google Places Autocomplete -------------------------
  var a = node(addr);
  if (a) {
    var ad = obj(a.data) || {};
    var st = str(ad.status);
    if (st !== 'OK' && st !== 'ZERO_RESULTS') {
      return { options: [], total: 0, count: 0, has_more: false, next_offset: null,
               error: 'address lookup is unavailable' };
    }
    var preds = arr(ad.predictions), opts = [];
    for (var j = 0; j < preds.length; j++) {
      var pr = obj(preds[j]) || {};
      // A prediction carries NO address components; the four leaves only exist
      // after the address_details hop (contract 7 §0).
      opts.push({ value: str(pr.place_id), text: str(pr.description) });
    }
    return page(opts, opts.length, 0, { reason: 'query' });
  }

  // ---- address details: Google Place Details -----------------------------
  var adt = node(addr_det);
  if (adt) {
    var dd = obj(adt.data) || {};
    if (str(dd.status) !== 'OK') {
      return { error: 'address lookup is unavailable' };
    }
    var res = obj(dd.result) || {};
    var comps = arr(res.address_components);
    var by = {};
    for (var c = 0; c < comps.length; c++) {
      var cc = obj(comps[c]) || {}, types = arr(cc.types);
      for (var t = 0; t < types.length; t++) {
        if (!by[types[t]]) by[types[t]] = { long: str(cc.long_name), short: str(cc.short_name) };
      }
    }
    function pick(k, which) { return by[k] ? by[k][which || 'long'] : ''; }
    // route SHORT: Google's own formatted_address abbreviates it ("Macquarie St",
    // not "Macquarie Street"), and so does every Australian address line.
    var street = (pick('street_number') + ' ' + pick('route', 'short')).replace(/^ +| +$/g, '');
    if (street === '') street = pick('subpremise') || pick('premise') || pick('establishment');
    var suburb = pick('locality') || pick('postal_town') || pick('sublocality_level_1') || pick('sublocality');
    return { option: {
      value: str(p.value), text: str(res.formatted_address),
      street: street, suburb: suburb,
      state: pick('administrative_area_level_1', 'short'), postcode: pick('postal_code')
    } };
  }

  // ---- ABN name search: ABR MatchingNames --------------------------------
  var an = node(abn);
  if (an) {
    var aj = jsonp(an.data);
    if (!aj) return { options: [], total: 0, count: 0, has_more: false, next_offset: null,
                      error: 'ABN lookup is unavailable' };
    var names = arr(aj.Names);
    if (names.length === 0 && str(aj.Message) !== '') {
      return { options: [], total: 0, count: 0, has_more: false, next_offset: null,
               error: str(aj.Message) };
    }
    var nopts = [];
    for (var n = 0; n < names.length; n++) {
      var nn = obj(names[n]) || {};
      nopts.push({
        value: str(nn.Abn), text: str(nn.Name),
        note: [str(nn.NameType), str(nn.State), str(nn.Postcode)].join(' ').replace(/ +/g, ' ').replace(/^ +| +$/g, ''),
        abn: str(nn.Abn), policyholder_name: str(nn.Name),
        state: str(nn.State), postcode: str(nn.Postcode)
      });
    }
    return page(nopts, nopts.length, 0, { reason: 'query' });
  }

  // ---- ABN details: ABR AbnDetails ---------------------------------------
  var adn = node(abn_det);
  if (adn) {
    var bj = jsonp(adn.data);
    if (!bj) return { error: 'ABN lookup is unavailable' };
    if (str(bj.Abn) === '' && str(bj.Message) !== '') return { error: str(bj.Message) };
    var trading = arr(bj.BusinessName);
    var row = {
      value: str(bj.Abn), text: str(bj.EntityName) + ' (' + str(bj.Abn) + ')',
      note: [str(bj.EntityTypeName), str(bj.AbnStatus)].join(' - '),
      abn: str(bj.Abn), policyholder_name: str(bj.EntityName),
      entity_type: str(bj.EntityTypeName), abn_status: str(bj.AbnStatus),
      state: str(bj.AddressState), postcode: str(bj.AddressPostcode),
      trading_name: trading.length > 0 ? str(trading[0]) : ''
    };
    // A name-search caller reaches this node too (PREPARE reroutes 11 digits),
    // and that caller is reading an option LIST.
    if (kind === 'abn') return page([row], 1, 0, { reason: 'query' });
    return { option: row };
  }

  return { options: [], total: 0, count: 0, has_more: false, next_offset: null,
           error: 'lookup produced no result' };
})()
